import { useEffect, useRef, useState, useCallback } from 'react';

export interface AgentActivity {
  state: 'idle' | 'thinking' | 'streaming' | 'tool_call';
  sessionKey?: string;
  runId?: string;
  text?: string;
  toolName?: string;
  toolArgs?: Record<string, unknown>;
  startedAt?: number;
  updatedAt: number;
}

const IDLE: AgentActivity = { state: 'idle', updatedAt: Date.now() };

/**
 * Subscribe to real-time agent activity via SSE.
 * Survives page refresh — reconnects and gets current state immediately.
 */
export function useAgentActivity(): AgentActivity {
  const [activity, setActivity] = useState<AgentActivity>(IDLE);
  const esRef = useRef<EventSource | null>(null);
  const retryRef = useRef<NodeJS.Timeout | null>(null);

  const connect = useCallback(() => {
    if (esRef.current) { try { esRef.current.close(); } catch {} }
    
    const es = new EventSource('/api/v1/events/stream');
    esRef.current = es;

    es.addEventListener('activity', (e) => {
      try {
        const data = JSON.parse((e as MessageEvent).data);
        setActivity(data);
      } catch {}
    });

    es.onerror = () => {
      es.close();
      esRef.current = null;
      // Reconnect after 2s
      if (!retryRef.current) {
        retryRef.current = setTimeout(() => {
          retryRef.current = null;
          connect();
        }, 2000);
      }
    };
  }, []);

  useEffect(() => {
    connect();
    return () => {
      if (esRef.current) esRef.current.close();
      if (retryRef.current) clearTimeout(retryRef.current);
    };
  }, [connect]);

  return activity;
}
